package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MathUtils_factorial_TriageGen0Test {

    @Test
    public void testFactorialZero() {
        // 0! = 1
        assertEquals(1L, MathUtils.factorial(0));
    }

    @Test
    public void testFactorialSmallValue() {
        // 5! = 120
        assertEquals(120L, MathUtils.factorial(5));
    }

    @Test
    public void testFactorialMediumValue() {
        // 12! = 479001600
        assertEquals(479001600L, MathUtils.factorial(12));
    }

    @Test
    public void testFactorialLimit() {
        // Testing a value that is large but still fits in a long
        // 20! is the largest factorial that fits in a signed 64-bit long
        // 20! = 2432902008176640000L
        assertEquals(2432902008176640000L, MathUtils.factorial(20));
    }

    @Test(expected = ArithmeticException.class)
    public void testFactorialOverflow() {
        // 21! exceeds Long.MAX_VALUE
        // The code checks if Math.round(factorialDouble(n)) == Long.MAX_VALUE
        // In many JVM implementations, factorialDouble(21) will result in a value 
        // that when rounded, triggers the ArithmeticException path.
        MathUtils.factorial(21);
    }
}
